<?php
$note = $note ?? [];
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>Delivery Note <?php echo htmlspecialchars($note['note_number'] ?? ''); ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.1/dist/css/bootstrap.min.css" rel="stylesheet"><style>@media print {.no-print{display:none!important} body{padding:0!important}}</style></head><body class="p-4"><div class="container"><div class="d-flex justify-content-between align-items-start mb-4"><div><h2 class="fw-bold">Delivery Note</h2><div>Note: <?php echo htmlspecialchars($note['note_number']); ?></div><div>Requisition: <?php echo htmlspecialchars($note['title']); ?></div></div><button class="btn btn-primary no-print" onclick="window.print()"><i class="bi bi-printer"></i> Print</button></div><div class="row mb-4"><div class="col-md-6"><strong>Issued to</strong><div><?php echo htmlspecialchars($note['issued_to'] ?? 'Requisition recipient/site'); ?></div></div><div class="col-md-6"><strong>Issued by</strong><div><?php echo htmlspecialchars($note['issued_by_name'] ?? ''); ?></div><div><?php echo htmlspecialchars($note['issued_at'] ?? ''); ?></div></div></div><table class="table table-bordered"><thead><tr><th>Item</th><th>Quantity</th><th>Stock source</th></tr></thead><tbody><?php foreach (($note['items'] ?? []) as $item): ?><tr><td><?php echo htmlspecialchars($item['item_name']); ?></td><td><?php echo number_format((float)$item['quantity'], 2); ?></td><td><?php echo htmlspecialchars(ucfirst($item['stock_type'])); ?></td></tr><?php endforeach; ?></tbody></table><div class="mt-5 row"><div class="col-6">Issued by: ____________________</div><div class="col-6">Received by: ____________________</div></div></div></body></html>
